def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((agent_id, opp))

    if budget <= 0:
        return 0.0

    if not alive:
        return float(min(budget, 18.0))

    units_available = int(supply / WATER_REQ)
    total_players = 1 + len(alive)
    scarcity = units_available < total_players

    highest_prev = 0.0
    urgent_prev = 0.0
    pressure_sum = 0.0
    pressure_count = 0

    for agent_id, opp in alive:
        prev = opp.get('previous_trace', {})
        bid = 0.0
        if prev and prev.get('bid') is not None:
            bid = float(prev.get('bid', 0.0))
            if bid > highest_prev:
                highest_prev = bid
            pressure_sum += bid
            pressure_count += 1

        opp_urgent = False
        if opp.get('no_water_days', 0) >= 1 or opp.get('hp', 10) <= 4:
            opp_urgent = True
        if prev and prev.get('status') == 'lost':
            opp_urgent = True
        if opp_urgent and bid > urgent_prev:
            urgent_prev = bid

    avg_prev = pressure_sum / pressure_count if pressure_count > 0 else 0.0

    danger = 0
    if hp <= 3:
        danger += 2
    elif hp <= 5:
        danger += 1
    if no_water_days >= 1:
        danger += 2

    if scarcity:
        if danger >= 3:
            target = max(92.0, highest_prev + 2.5, urgent_prev + 2.5)
        elif danger >= 1:
            target = max(74.0, avg_prev + 4.0, urgent_prev + 2.0)
        else:
            if highest_prev >= 120.0:
                target = 46.0
            elif highest_prev >= 90.0:
                target = 58.0
            else:
                target = max(52.0, avg_prev * 0.78)
    else:
        if danger >= 3:
            target = max(72.0, avg_prev + 1.5)
        elif danger >= 1:
            target = 44.0
        else:
            target = 24.0

    if day >= 8:
        if danger >= 1:
            target += 8.0
        else:
            target += 3.0

    if budget < target:
        if danger >= 3:
            target = budget
        elif danger >= 1:
            target = max(0.0, min(budget, budget * 0.92))
        else:
            target = max(0.0, min(budget, budget * 0.7))

    target = min(target, budget)
    if target < 0:
        target = 0.0
    return float(target)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    if num_alive_opponents == 0:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    base_bid = DAILY_SALARY * 0.55

    if my_status['hp'] <= 2:
        base_bid = DAILY_SALARY * 0.95
    elif my_status['hp'] <= 4:
        base_bid = DAILY_SALARY * 0.8
    elif my_status['hp'] <= 6:
        base_bid = DAILY_SALARY * 0.7

    if my_status['no_water_days'] > 0:
        base_bid = max(base_bid, DAILY_SALARY * 0.9)

    if day_context['day'] == EPISODE_DAYS:
        if my_status['hp'] < EPISODE_DAYS:
            return my_status['budget']
        else:
            return min(my_status['budget'], DAILY_SALARY * 0.2)

    yesterday_opponent_bids = []
    for opp_id, opp_data in opponents_status.items():
        if opp_data['alive']:
            prev_trace = opp_data.get('previous_trace', {})
            if prev_trace and prev_trace.get('bid') is not None:
                yesterday_opponent_bids.append(prev_trace['bid'])

    if yesterday_opponent_bids:
        highest_prev_bid = max(yesterday_opponent_bids)

        if my_status['hp'] <= 4:
            base_bid = max(base_bid, highest_prev_bid + 5)
        elif my_status['hp'] <= 6:
            base_bid = max(base_bid, highest_prev_bid + 3)
        else:
            current_supply = day_context['supply']
            if current_supply < WATER_REQ * 1.5 and highest_prev_bid > DAILY_SALARY * 0.8:
                base_bid = max(base_bid, DAILY_SALARY * 0.6)
            else:
                base_bid = max(base_bid, highest_prev_bid + 1.5)

    final_bid = min(my_status['budget'], base_bid)
    final_bid = max(1.0, final_bid)

    return final_bid

